<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    \\$acl.AddAccessRule((</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">New-Object</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> System.Security.AccessControl.FileSystemAccessRule(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;BUILTIN\\Administrators&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;FullControl&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Allow&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)))</span></span>
